// THUẬT TOÁN ĐÁNH GIÁ & CHẤM ĐIỂM KOC TỰ ĐỘNG (AUTO-VETTING)
const results = [];

for (const item of $input.all()) {
  const data = item.json.body || item.json;
  if (!data || !data.kocName) continue;

  let score = 0;
  const reasons = [];

  // 1. Chấm điểm theo Follower
  const followersCount = Number(data.followersCount) || (parseInt(data.followers) * (String(data.followers).toLowerCase().includes('k') ? 1000 : 1)) || 0;
  if (followersCount >= 10000) {
    score += 45;
    reasons.push('Followers lớn (>=10k: +45đ)');
  } else if (followersCount >= 3000) {
    score += 35;
    reasons.push('Followers khá (>=3k: +35đ)');
  } else if (followersCount >= 1000) {
    score += 25;
    reasons.push('Nano KOC chuẩn (>=1k: +25đ)');
  } else if (followersCount >= 500) {
    score += 15;
    reasons.push('Kênh mới tiềm năng (>=500: +15đ)');
  } else {
    score += 5;
    reasons.push('Kênh dưới 500 follow (+5đ)');
  }

  // 2. Chấm điểm theo GMV & Đơn bán/tháng
  const gmvStr = String(data.monthlyAvgGmv || data.gmv || '').toLowerCase();
  const ordersStr = String(data.monthlyOrders || '').toLowerCase();

  if (gmvStr.includes('triệu') || gmvStr.includes('tr') || parseInt(gmvStr) >= 10000000) {
    score += 35;
    reasons.push('Có GMV thực tế ấn tượng (+35đ)');
  } else if (ordersStr.includes('đơn') || parseInt(ordersStr) >= 30) {
    score += 25;
    reasons.push('Có đơn bán hàng tháng (+25đ)');
  }

  // 3. Chấm điểm Ý tưởng video (Concept)
  const concept = String(data.contentConcept || '');
  if (concept.length >= 30) {
    score += 20;
    reasons.push('Ý tưởng video chi tiết (+20đ)');
  } else if (concept.length > 5) {
    score += 10;
    reasons.push('Có ý tưởng video (+10đ)');
  }

  // Phân loại quyết định
  let decision = 'MANUAL_REVIEW';
  let badge = '⏳ CẦN DUYỆT TAY';

  if (score >= 65) {
    decision = 'AUTO_APPROVE';
    badge = '⚡ ĐỦ ĐIỀU KIỆN DUYỆT NHANH (VIP)';
  } else if (score < 20) {
    decision = 'AUTO_REJECT';
    badge = '❌ KHÔNG ĐẠT TIÊU CHÍ';
  }

  const rawHandle = data.tiktokHandle || 'koc';
  const cleanHandle = rawHandle.startsWith('@') ? rawHandle.slice(1) : rawHandle;

  results.push({
    json: {
      ...data,
      score,
      reasons: reasons.join(' • '),
      decision,
      badge,
      cleanHandle
    }
  });
}

return results;

